<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>可衣 - 都市女性的日常穿搭之选</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
            color: #2d2d2d;
            background: #fff;
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        .top-bar {
            background: #f8f5f2;
            text-align: center;
            padding: 10px 20px;
            font-size: 13px;
            color: #666;
            letter-spacing: 1px;
        }

        header {
            background: #fff;
            border-bottom: 1px solid #eee;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-inner {
            max-width: 1440px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 40px;
            height: 72px;
        }

        .logo {
            font-size: 28px;
            font-weight: 700;
            letter-spacing: 4px;
            color: #2d2d2d;
        }

        .logo span {
            color: #c4956a;
        }

        nav {
            display: flex;
            gap: 36px;
        }

        nav a {
            font-size: 15px;
            color: #555;
            transition: color 0.3s;
            padding: 8px 0;
            border-bottom: 2px solid transparent;
        }

        nav a:hover,
        nav a.active {
            color: #2d2d2d;
            border-bottom-color: #c4956a;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .cart-icon {
            position: relative;
            cursor: pointer;
        }

        .cart-icon svg {
            width: 24px;
            height: 24px;
        }

        .cart-badge {
            position: absolute;
            top: -6px;
            right: -8px;
            background: #c4956a;
            color: #fff;
            font-size: 11px;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .hero {
            position: relative;
            height: 560px;
            background: linear-gradient(135deg, #f8f5f2 0%, #ede4da 50%, #e8d5c4 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: -50%;
            right: -20%;
            width: 600px;
            height: 600px;
            border-radius: 50%;
            background: rgba(196, 149, 106, 0.08);
        }

        .hero::after {
            content: '';
            position: absolute;
            bottom: -30%;
            left: -10%;
            width: 400px;
            height: 400px;
            border-radius: 50%;
            background: rgba(196, 149, 106, 0.06);
        }

        .hero-content {
            position: relative;
            z-index: 2;
        }

        .hero-content h1 {
            font-size: 48px;
            font-weight: 300;
            letter-spacing: 8px;
            margin-bottom: 16px;
            color: #2d2d2d;
        }

        .hero-content p {
            font-size: 18px;
            color: #777;
            margin-bottom: 36px;
            letter-spacing: 2px;
        }

        .hero-btn {
            display: inline-block;
            padding: 14px 48px;
            background: #2d2d2d;
            color: #fff;
            font-size: 15px;
            letter-spacing: 2px;
            transition: all 0.3s;
        }

        .hero-btn:hover {
            background: #c4956a;
            transform: translateY(-2px);
        }

        .section {
            max-width: 1440px;
            margin: 0 auto;
            padding: 80px 40px;
        }

        .section-title {
            text-align: center;
            margin-bottom: 48px;
        }

        .section-title h2 {
            font-size: 28px;
            font-weight: 400;
            letter-spacing: 4px;
            margin-bottom: 12px;
        }

        .section-title p {
            font-size: 14px;
            color: #999;
        }

        .category-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .category-card {
            position: relative;
            height: 320px;
            background: #f8f5f2;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s;
            overflow: hidden;
        }

        .category-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 40px rgba(0,0,0,0.08);
        }

        .category-card:nth-child(1) { background: linear-gradient(135deg, #fdf2f0, #f8e8e4); }
        .category-card:nth-child(2) { background: linear-gradient(135deg, #f0f4fd, #e4ecf8); }
        .category-card:nth-child(3) { background: linear-gradient(135deg, #f2fdf4, #e4f8e8); }
        .category-card:nth-child(4) { background: linear-gradient(135deg, #fdf8f0, #f8f0e4); }

        .category-icon {
            font-size: 48px;
            margin-bottom: 16px;
        }

        .category-card h3 {
            font-size: 18px;
            font-weight: 500;
            margin-bottom: 8px;
        }

        .category-card p {
            font-size: 13px;
            color: #999;
        }

        .new-arrivals {
            background: #fafafa;
        }

        .product-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .product-card {
            background: #fff;
            transition: all 0.3s;
            cursor: pointer;
        }

        .product-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 40px rgba(0,0,0,0.08);
        }

        .product-image {
            position: relative;
            height: 320px;
            background: #f5f0eb;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }

        .product-image .placeholder-icon {
            font-size: 64px;
            opacity: 0.6;
        }

        .product-tag {
            position: absolute;
            top: 12px;
            left: 12px;
            background: #c4956a;
            color: #fff;
            font-size: 11px;
            padding: 4px 10px;
            letter-spacing: 1px;
        }

        .product-info {
            padding: 16px;
        }

        .product-info h3 {
            font-size: 15px;
            font-weight: 400;
            margin-bottom: 8px;
            color: #333;
        }

        .product-info .price {
            font-size: 16px;
            color: #c4956a;
            font-weight: 500;
        }

        .product-info .price .original {
            font-size: 13px;
            color: #bbb;
            text-decoration: line-through;
            margin-left: 8px;
        }

        .features {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 40px;
            text-align: center;
        }

        .feature-item {
            padding: 32px 24px;
        }

        .feature-icon {
            font-size: 36px;
            margin-bottom: 16px;
        }

        .feature-item h3 {
            font-size: 16px;
            margin-bottom: 8px;
            font-weight: 500;
        }

        .feature-item p {
            font-size: 13px;
            color: #999;
            line-height: 1.8;
        }

        .banner-section {
            background: linear-gradient(135deg, #2d2d2d, #4a3f35);
            padding: 80px 40px;
            text-align: center;
            color: #fff;
        }

        .banner-section h2 {
            font-size: 32px;
            font-weight: 300;
            letter-spacing: 4px;
            margin-bottom: 16px;
        }

        .banner-section p {
            font-size: 15px;
            color: rgba(255,255,255,0.7);
            margin-bottom: 32px;
        }

        .banner-btn {
            display: inline-block;
            padding: 14px 48px;
            border: 1px solid rgba(255,255,255,0.6);
            color: #fff;
            font-size: 14px;
            letter-spacing: 2px;
            transition: all 0.3s;
        }

        .banner-btn:hover {
            background: #fff;
            color: #2d2d2d;
        }

        footer {
            background: #1a1a1a;
            color: #ccc;
            padding: 60px 40px 30px;
        }

        .footer-inner {
            max-width: 1440px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 48px;
            margin-bottom: 40px;
        }

        .footer-brand .logo {
            color: #fff;
            margin-bottom: 16px;
        }

        .footer-brand p {
            font-size: 13px;
            line-height: 1.8;
            color: #999;
        }

        .footer-col h4 {
            color: #fff;
            font-size: 15px;
            margin-bottom: 16px;
        }

        .footer-col a {
            display: block;
            font-size: 13px;
            color: #999;
            margin-bottom: 10px;
            transition: color 0.3s;
        }

        .footer-col a:hover {
            color: #c4956a;
        }

        .footer-bottom {
            max-width: 1440px;
            margin: 0 auto;
            padding-top: 24px;
            border-top: 1px solid #333;
            text-align: center;
            font-size: 12px;
            color: #666;
        }

        @media (max-width: 1024px) {
            .category-grid,
            .product-grid {
                grid-template-columns: repeat(2, 1fr);
            }
            .footer-inner {
                grid-template-columns: 1fr 1fr;
            }
        }

        @media (max-width: 768px) {
            .header-inner {
                padding: 0 20px;
            }
            nav {
                display: none;
            }
            .hero {
                height: 400px;
            }
            .hero-content h1 {
                font-size: 32px;
            }
            .section {
                padding: 48px 20px;
            }
            .category-grid,
            .product-grid {
                grid-template-columns: 1fr;
            }
            .features {
                grid-template-columns: 1fr;
            }
            .footer-inner {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
<body>
